from __future__ import annotations

import json
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
REPORT_FILE = TASK_DIR / "outputs" / "public_reproduction_report.json"


def write_report(status: str, inputs_validated: bool, complete_workflow_usable: bool, exit_code: int) -> int:
    report = {
        "schema_version": "1.0",
        "status": status,
        "observation": {
            "inputs_validated": inputs_validated,
            "complete_workflow_usable": complete_workflow_usable,
        },
    }
    REPORT_FILE.parent.mkdir(exist_ok=True)
    payload = json.dumps(report, indent=2, sort_keys=True) + "\n"
    REPORT_FILE.write_text(payload, encoding="utf-8")
    print(payload, end="")
    return exit_code


def main() -> int:
    try:
        from workflow.session_pipeline import run_archived_session, validate_archived_session

        validate_archived_session(TASK_DIR)
    except Exception:  # noqa: BLE001 - initialization failures have a separate lifecycle state.
        return write_report("runner_failure", False, False, 2)

    try:
        usable = bool(run_archived_session(TASK_DIR))
    except (ArithmeticError, LookupError, RuntimeError, ValueError):
        return write_report("pre_fix_expected_failure", True, False, 1)
    except Exception:  # noqa: BLE001 - unexpected execution failures are not scientific observations.
        return write_report("runner_failure", True, False, 2)

    if usable:
        return write_report("post_fix_success", True, True, 0)
    return write_report("pre_fix_expected_failure", True, False, 1)


if __name__ == "__main__":
    raise SystemExit(main())
